discrete FaultDetectionAndIsolationSystem
port:
    event input real FaultSignal;
    event output real IsolationStatus;
state:
    initial state NormalOperationState
        when entry() then
            statehold(0);
        end;
        when receive(FaultSignal) then
            transition(FaultDetectionState);
        end;
    end;

    state FaultDetectionState
        when entry() then
            statehold(0);
        end;
        when receive(FaultSignal) then
            transition(FaultIsolationState);
            out
                send(IsolationStatus, 1);
        end;
        when timeover() then
            transition(NormalOperationState);
        end;
    end;

    state FaultIsolationState
        when entry() then
            statehold(0);
        end;
        when receive(FaultSignal) then
            transition(FaultIsolationState);
            out
                send(IsolationStatus, 1);
        end;
        when timeover() then
            transition(NormalOperationState);
            out
                send(IsolationStatus, 0);
        end;
    end;
end;
end;

discrete EnergyManagementSystem
port:
    event input real EnergyDemandIncrease;
    event output real EnergyStabilityStatus;
state:
    initial state StandbyState
        when entry() then
            statehold(0);
        end;
        when receive(EnergyDemandIncrease) then
            transition(EnergySchedulingState);
        end;
    end;

    state EnergySchedulingState
        when entry() then
            statehold(0);
        end;
        when receive(EnergyDemandIncrease) then
            transition(EnergyStableState);
            out
                send(EnergyStabilityStatus, 1);
        end;
        when timeover() then
            transition(EnergySchedulingState);
            out
                send(EnergyStabilityStatus, 0);
        end;
    end;

    state EnergyStableState
        when entry() then
            statehold(0);
        end;
        when receive(EnergyDemandIncrease) then
            transition(EnergySchedulingState);
        end;
        when timeover() then
            transition(EnergySchedulingState);
        end;
    end;
end;
end;

discrete PowerExtractionAndDistributionSystem
port:
    event input real PowerDemandIncrease;
    event output real PowerDistributionStatus;
state:
    initial state StandbyState
        when entry() then
            statehold(0);
        end;
        when receive(PowerDemandIncrease) then
            transition(PowerExtractionState);
        end;
    end;

    state PowerExtractionState
        when entry() then
            statehold(0);
        end;
        when receive(PowerDemandIncrease) then
            transition(PowerDistributionState);
            out
                send(PowerDistributionStatus, 1);
        end;
        when timeover() then
            transition(PowerExtractionState);
            out
                send(PowerDistributionStatus, 0);
        end;
    end;

    state PowerDistributionState
        when entry() then
            statehold(0);
        end;
        when receive(PowerDemandIncrease) then
            transition(PowerExtractionState);
        end;
        when timeover() then
            transition(PowerExtractionState);
        end;
    end;
end;
end;

